import java.util.List;
import java.util.Map;
import java.util.Optional;

public class OptionalFlattenerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final Map<String, String> ALIASES = Map.of("db", "db-main", "cache", "cache-1");
    static final Map<String, String> HOSTS = Map.of("db-main", "10.0.0.5", "web-1", "10.0.0.9");

    static List<Optional<String>> mixed() {
        return List.of(Optional.of("a"), Optional.empty(), Optional.of("bb"), Optional.empty());
    }

    public static void main(String[] args) {
        checkCall("present values kept in order", "[a, bb]",
                () -> OptionalFlattener.presentValues(mixed()).toString());
        checkCall("all empty", "[]",
                () -> OptionalFlattener.presentValues(List.of(Optional.empty(), Optional.empty())).toString());
        checkCall("nothing to flatten", "[]",
                () -> OptionalFlattener.presentValues(List.of()).toString());

        check("total length of present values", 3, OptionalFlattener.totalLength(mixed()));
        check("total length with nothing present", 0,
                OptionalFlattener.totalLength(List.of(Optional.empty())));
        check("total length of one value", 5,
                OptionalFlattener.totalLength(List.of(Optional.of("hello"))));

        check("both hops succeed", Optional.of("10.0.0.5"),
                OptionalFlattener.resolve(Optional.of("db"), ALIASES, HOSTS));
        check("second hop missing", Optional.empty(),
                OptionalFlattener.resolve(Optional.of("cache"), ALIASES, HOSTS));
        check("first hop missing", Optional.empty(),
                OptionalFlattener.resolve(Optional.of("mail"), ALIASES, HOSTS));
        check("empty alias", Optional.empty(),
                OptionalFlattener.resolve(Optional.empty(), ALIASES, HOSTS));
        done();
    }
}

