import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * TASK: Complete OptionalFlattener.
 *
 * - presentValues(values) turns a List<Optional<String>> into a List<String>
 *   holding only the values that are present, in order. The neat way is
 *   values.stream().flatMap(Optional::stream) -- Optional.stream() gives a
 *   stream of one element for a present Optional and an empty stream for an
 *   absent one, so the empties simply vanish.
 *   [Optional[a], Optional.empty, Optional[bb]] -> [a, bb]
 *
 * - totalLength(values) adds up the lengths of the present values only, so the
 *   list above gives 3.
 *
 * - resolve(alias, aliases, hosts) follows two hops: the alias names an entry
 *   in aliases, whose value names an entry in hosts. Any missing hop -- an
 *   empty alias included -- gives an empty Optional. Chain it with flatMap and
 *   Optional.ofNullable; do NOT use isPresent or get.
 *   With aliases {db=db-main} and hosts {db-main=10.0.0.5},
 *   resolve(Optional.of("db"), ...) -> Optional[10.0.0.5]
 */
public class OptionalFlattener {

    public static List<String> presentValues(List<Optional<String>> values) {
        return values.stream()
                .flatMap(Optional::stream)
                .collect(Collectors.toList());
    }

    public static int totalLength(List<Optional<String>> values) {
        return values.stream()
                .flatMap(Optional::stream)
                .mapToInt(String::length)
                .sum();
    }

    public static Optional<String> resolve(Optional<String> alias,
                                           Map<String, String> aliases,
                                           Map<String, String> hosts) {
        return alias
                .flatMap(name -> Optional.ofNullable(aliases.get(name)))
                .flatMap(target -> Optional.ofNullable(hosts.get(target)));
    }
}
